#!/usr/bin/env python3
"""Reproduz o pacote curado a partir do PDF BASA 2013 fornecido pelo usuário.
Requer PyMuPDF. Não tenta aprovar automaticamente o restante do acervo.
Uso: python3 tools/build_curated_pack.py /caminho/basa0113_prova_01_merged.pdf /saida/pacote.json
"""
import sys, re, json, hashlib
from pathlib import Path
import fitz
ROOT=Path(__file__).resolve().parents[1]
# Número: assunto, explicação geral, justificativas A-E. Autoria didática, não oficial.
NOTES={
10: ('Redação oficial','Concisão elimina palavras desnecessárias, não informações essenciais. Clareza exige preservar o conteúdo necessário ao entendimento; por isso a exceção é D.', ['Formalidade e padronização dão uniformidade à comunicação oficial.','Retirar excessos linguísticos mantém o conteúdo e melhora a concisão.','A impessoalidade evita que marcas pessoais gerem interpretações inadequadas.','Eliminar passagens substanciais pode retirar informação indispensável; concisão não significa mutilar o conteúdo.','A norma culta e a ausência de jargões restritos favorecem compreensão ampla.']),
12: ('Sistema de Amortização Constante','No SAC, a amortização A é igual em todas as parcelas. Antes da 25ª parcela restam 25 amortizações: prestação = A + 0,01 × 25A = 1,25A. Como 1,25A = 5.000, A = 4.000. Após 48 das 49 parcelas, resta uma amortização: R$ 4.000.', ['É o saldo de uma amortização restante, calculada por 5.000/1,25.','Acrescenta juros ao saldo, embora se peça apenas o principal após a 48ª parcela.','Não resulta da relação 1,25A = 5.000 do SAC.','Não corresponde a uma amortização constante de R$ 4.000.','É o valor da 25ª prestação, que inclui juros, não o saldo pedido.']),
13: ('Média ponderada de dados agrupados','Para estimar a média, use os pontos médios das classes: 0,5; 1,5; 2,5; 4; 7,5; e 15 salários mínimos. O grupo sem rendimentos contribui com zero. Multiplique cada ponto médio por sua frequência: 0,5×0,30 + 1,5×0,30 + 2,5×0,10 + 4×0,10 + 7,5×0,08 + 15×0,02 + 0×0,10 = 0,15+0,45+0,25+0,40+0,60+0,30 = 2,15. Frequências diferentes impedem tirar a média simples dos pontos médios.', ['2,05 fica 0,10 abaixo da soma das contribuições ponderadas; o grupo sem renda entra com valor zero, sem subtrair 0,10 da média.','2,15 é a soma dos pontos médios ponderados pelas frequências relativas.','2,35 excede a soma ponderada em 0,20; é necessário multiplicar cada ponto médio por sua própria frequência.','2,45 excede o total em 0,30; a contribuição da classe de 10 a 20 salários já está incluída uma vez.','2,65 excede o total em 0,50; os grupos de maior renda não podem receber pesos maiores que suas frequências.']),
16: ('Juros compostos equivalentes','Igualando os montantes: C(1,01)^48 = C(1+i)^24. Logo 1+i = (1,01)^2 = 1,0201, e i = 2,01% ao mês. Dobrar o prazo não equivale simplesmente a dobrar a taxa, pois há juros sobre juros.', ['2% é a aproximação linear; ignora o produto dos juros compostos.','2,01% reproduz exatamente o fator 1,01².','2,02% supera a taxa equivalente calculada.','2,1% supera 2,01% e produziria montante maior.','2,2% também produziria montante maior.']),
17: ('Saldo devedor e juros compostos','Após um mês: 1.500 × 1,02 = 1.530. Pagando 750, restam 780. No mês seguinte o saldo cresce para 780 × 1,02 = 795,60. Os juros do segundo mês incidem sobre o saldo restante.', ['750 ignora os juros cobrados desde a compra.','765 aplica um único mês de juros sobre 750, sem calcular o saldo correto.','780 é o saldo logo após a primeira parcela, antes dos juros do segundo mês.','795,60 resulta de (1.500 × 1,02 − 750) × 1,02.','810 não corresponde à evolução mensal do saldo devedor.']),
35: ('Comércio exterior: Siscomex','O Siscomex integra o registro e o controle de operações de comércio exterior. A pergunta trata da expansão histórica de 1997, quando passou a abranger também os registros das importações brasileiras.', ['Fluxos de capital financeiro não são a expansão histórica específica pedida.','A inclusão das importações complementou o tratamento inicial das exportações.','Controlar cotações cambiais não é a finalidade descrita.','As reservas internacionais não são o cadastro de importações.','Capitais financeiros de curto prazo não são operações de importação de mercadorias.']),
36: ('Debêntures','Debêntures representam dívida da companhia. Ao emiti-las, a empresa capta recursos sem emitir novas ações naquele momento, preservando a distribuição da propriedade. Algumas podem ser conversíveis, mas essa característica não é obrigatória.', ['Não existe limitação geral de vencimento a 90 dias para debêntures.','Companhias fechadas também podem emitir debêntures; oferta pública envolve regras próprias.','A emissão de dívida não pulveriza, por si só, a propriedade acionária.','A conversão em ações depende das condições de emissão; não ocorre sempre.','Debêntures podem ter garantias; não são necessariamente desprovidas delas.']),
37: ('Sociedades anônimas','Na sociedade anônima, a responsabilidade do acionista se limita ao preço de emissão das ações subscritas ou adquiridas. Fechada significa que não tem valores mobiliários admitidos à negociação no mercado de valores mobiliários. A alternativa A expressa a limitação de responsabilidade de forma simplificada.', ['É a alternativa que expressa a responsabilidade limitada do acionista; observe o limite legal do preço de emissão.','Ações podem ser transferidas sem alterar um contrato social a cada entrada ou saída.','Negociação em bolsa é característica de companhia aberta, não fechada.','A identificação dos titulares é mantida nos registros de ações, não exige que todos os nomes constem no estatuto.','Sociedade anônima tem capital dividido em ações, não em cotas de uma limitada.']),
39: ('Proteção cambial','A obrigação vence em 180 dias e compreende principal mais juros em dólares. A proteção deve cobrir esse mesmo valor e prazo: vender os dólares recebidos no presente e contratar sua compra futura para quitar a dívida reduz a exposição à variação cambial.', ['Protege só os juros e deixa o principal descoberto.','O vencimento de 90 dias não coincide com a dívida de 180 dias.','Alinha valor total e prazo da compra de dólares à obrigação.','Comprar no mercado pronto não é a combinação futura descrita.','Vender dólares futuros cria posição oposta à necessária para pagar a dívida.']),
40: ('Taxas de câmbio cruzadas','Um dólar vale R$ 2 e £ 0,50. Portanto uma libra vale dois dólares: 2 × R$ 2 = R$ 4. Outra forma é dividir 2 R$/US$ por 0,50 £/US$, obtendo 4 R$/£.', ['0,5 é a cotação em libras por dólar, não reais por libra.','1 não resulta da divisão das taxas na unidade pedida.','2 é o valor em reais de um dólar, não de uma libra.','3 não é a razão entre 2 e 0,50.','4 R$/£ resulta da divisão 2/0,50.']),
41: ('Estrutura do Sistema Financeiro Nacional','O SFN se organiza em órgãos normativos, que estabelecem regras; entidades supervisoras, que fiscalizam; e operadores, que prestam serviços financeiros. Exemplo: CMN, Banco Central e bancos, respectivamente.', ['Classifica por natureza pública ou governamental, sem refletir os três papéis institucionais.','Entidades filantrópicas não constituem um dos três segmentos do SFN.','Reúne corretamente os papéis de normatizar, supervisionar e operar.','A divisão público/privado e ONGs não corresponde à estrutura funcional do SFN.','Repete a ideia de supervisão e omite operadores e órgãos normativos.']),
42: ('Banco Central','O CMN define diretrizes gerais de política monetária e creditícia. O Banco Central executa essas orientações e atua para preservar o poder de compra da moeda. É necessário distinguir quem formula as diretrizes de quem as executa.', ['A Susep supervisiona seguros, não executa a política monetária geral.','O Banco Central é o executor indicado no enunciado.','A bolsa organiza mercados, não é a autoridade monetária.','O CNSP estabelece diretrizes para seguros privados.','A Caixa é instituição financeira operadora, não a autoridade monetária.']),
43: ('Seguros: endosso','Endosso é o documento pelo qual se formalizam alterações em uma apólice durante sua vigência. Ao substituir o veículo ou acrescentar cobertura, o segurado solicita endosso; pode haver ajuste do prêmio conforme o novo risco.', ['O endosso registra a mudança contratual na apólice.','Reembolso de prêmio é devolução de valor e não formaliza a alteração desejada.','Estorno desfaz cobrança ou pagamento, não substitui o bem segurado.','Cancelar encerra o contrato, em vez de ajustá-lo.','Prêmio é o preço do seguro, não o instrumento de alteração.']),
44: ('Caixa e FGTS','A Caixa atua como agente operador do Fundo de Garantia do Tempo de Serviço. O FGTS reúne depósitos vinculados aos trabalhadores e tem regras próprias de saque e aplicação. Não se deve confundi-lo com o Fundo Garantidor de Créditos.', ['Pensão alimentícia é obrigação familiar, não o fundo referido.','Um FIDC não é o fundo trabalhista administrado pela Caixa nesse papel.','Investimento público é expressão genérica que não identifica o FGTS.','É o Fundo de Garantia do Tempo de Serviço, objeto da função da Caixa.','O FGC protege determinados créditos contra instituições financeiras e não se confunde com o FGTS.']),
45: ('BNDES','O BNDES atua principalmente no financiamento do desenvolvimento com foco em investimentos de prazo mais longo, equipamentos e exportações. A alternativa B descreve esse conjunto de forma ampla, sem restringi-lo a setores ou importações específicos.', ['Capital de giro pode ser apoiado, mas a opção não descreve o foco amplo de longo prazo pedido.','Projetos, equipamentos e exportações expressam as principais linhas de apoio apresentadas.','Limita indevidamente a atuação a petróleo e indústria têxtil.','Restringe o apoio à importação de insumos de um único setor.','Restringe o apoio a insumos agrícolas e importação para pequenos produtores.']),
46: ('Arrendamento mercantil','Leasing é arrendamento mercantil: o arrendador disponibiliza um bem mediante contraprestações, conforme a modalidade e o contrato. Não é a mesma operação que comprar recebíveis ou fazer um derivativo de troca de riscos.', ['Leasing é a denominação da operação de arrendamento mercantil.','Factoring envolve aquisição de direitos creditórios e serviços associados.','Underwriting está ligado à colocação de valores mobiliários.','Office banking designa canais ou serviços bancários para empresas.','Swap é um derivativo de troca de fluxos ou riscos financeiros.']),
49: ('Factoring','Na operação descrita, a empresa recebe antecipadamente pela venda de seus direitos creditórios a uma sociedade de fomento mercantil, com desconto. Esse é o núcleo do factoring, que pode incluir serviços de gestão de recebíveis.', ['Associações de poupança não são o agente típico de fomento mercantil descrito.','Arrendamento mercantil disponibiliza bens para uso, não é a compra de recebíveis descrita.','Cooperativas podem realizar serviços financeiros, mas não identificam a modalidade de fomento mercantil pedida.','Sociedades de fomento mercantil realizam factoring.','Distribuidoras atuam na distribuição e intermediação de valores mobiliários.']),
50: ('Cobrança bancária','No fluxo de cobrança por boleto, o pagamento é processado e o crédito segue para a conta cadastrada do beneficiário, conforme os prazos e condições de liquidação. Não é necessário pedir uma transferência adicional a cada boleto pago.', ['Não precisa solicitar individualmente cada crédito de boleto já processado.','O crédito é automático na conta cadastrada, observado o prazo de liquidação.','O fluxo não exige retirar uma ordem de pagamento.','Não é necessário que o pagador emita um DOC adicional; o boleto já foi pago.','O processamento bancário não depende de ordem de pagamento posterior emitida pelo sacado.']),
51: ('Canais digitais','Remote banking significa realizar operações bancárias a distância, reduzindo a necessidade de ir à agência. O banco pela internet é o exemplo direto de canal remoto, ao contrário de documentos ou instrumentos de pagamento por si sós.', ['Um cheque pré-datado não é um canal de atendimento remoto.','O cartão é um instrumento de pagamento e crédito, não o exemplo direto do canal pedido.','Boleto é um instrumento de cobrança; sua existência não caracteriza atendimento remoto.','Internet banking permite consultar e operar a distância.','Duplicata é um título ligado a uma operação comercial, não um canal remoto.']),
52: ('Commercial papers','Commercial papers são notas promissórias comerciais usadas na captação de curto prazo por empresas. A pergunta se refere ao instrumento de dívida emitido pela empresa para financiar suas necessidades de capital de giro.', ['Títulos públicos são emitidos pelo poder público.','Hot money é uma operação de crédito de curtíssimo prazo, não o título emitido descrito.','Commercial papers correspondem ao instrumento de captação empresarial pedido.','Factoring envolve cessão de recebíveis e serviços, não emissão desse título.','Títulos federais são emitidos pelo governo federal, não pela empresa.']),
54: ('Finanças corporativas','Corporate finance abrange decisões e operações de estrutura de capital e reorganização empresarial. Na questão, a atividade típica é assessorar aquisições, cisões, incorporações e fusões, que alteram a estrutura ou o controle de empresas.', ['Manter atividades de estrangeiras é descrição vaga que não identifica as operações societárias pedidas.','Reúne operações clássicas de reorganização e combinação de empresas.','Negociar letras de câmbio não descreve o foco de reorganização societária da questão.','Debêntures são captação; a alternativa B identifica mais diretamente o conjunto de operações complexas pedido.','Intermediar títulos públicos pertence à atuação no mercado de títulos, não ao foco societário pedido.']),
55: ('CDB e RDB','CDB e RDB são instrumentos de captação das instituições financeiras e representam depósitos a prazo. Os recursos captados financiam operações de crédito. Não se confundem com títulos do Tesouro nem com debêntures corporativas.', ['Títulos públicos federais são dívida do governo, não captação bancária por depósito a prazo.','Letras do Tesouro são instrumentos públicos, não os títulos bancários pedidos.','A combinação apresentada não identifica CDB e RDB.','Mistura títulos públicos com debêntures, que não são os depósitos a prazo bancários.','Certificados e recibos de depósito bancário correspondem a CDB e RDB.']),
56: ('Crédito direto ao consumidor','O CDC financia aquisição de bens e serviços pelo consumidor. A liquidação antecipada deve considerar a redução proporcional de juros e demais acréscimos cabíveis; a dívida futura não é simplesmente somada sem desconto.', ['Leasing é arrendamento; não é o empréstimo de CDC descrito.','CDI é instrumento interfinanceiro, não financiamento ao consumidor.','Cartão de crédito é meio de pagamento com modalidades próprias, não a modalidade específica pedida.','CDC é o crédito destinado à aquisição de bens e serviços descrito.','Hot money atende necessidades de curtíssimo prazo, tipicamente de empresas.']),
58: ('Desconto de títulos','No desconto bancário, o banco antecipa ao cliente o valor de um recebível antes do vencimento, descontando juros e encargos. Por exemplo, um título de R$ 1.000 a vencer pode gerar hoje crédito menor que esse valor.', ['Descreve a antecipação do recebível mediante cobrança de juros.','Prorrogar o vencimento é postergar, enquanto desconto antecipa recursos.','Quitar uma dívida antecipadamente é diferente de antecipar um direito de recebimento.','Desconto em tarifa de internet banking não é desconto bancário de títulos.','Vincular recebíveis a bens móveis ou imóveis não define essa operação.']),
59: ('Garantias: aval','Aval é garantia pessoal ligada a título de crédito. O avalista assume obrigação autônoma e responde pelo pagamento conforme as regras do título. Diferentemente de uma garantia real, o aval não é constituído sobre um bem específico.', ['Descreve garantia real sobre imóvel, não aval.','Define a garantia pessoal autônoma destinada a assegurar título de crédito.','A entrega de bem móvel é característica de penhor, não aval.','A titularidade fiduciária de bem móvel remete à alienação fiduciária.','A descrição genérica não define o aval e usa classificação inadequada de garantia impessoal.'])}

def clean(s):
    s=re.sub(r'(\w)-\s*\n\s*(\w)',r'\1\2',s)
    return re.sub(r'\s+',' ',s).strip()

def build(pdf, output):
    digest=hashlib.sha256(pdf.read_bytes()).hexdigest()
    expected=''
    manifest=json.loads((ROOT/'docs/materials.json').read_text())
    expected=next(x['sha256'] for x in manifest if x['file']==pdf.name)
    assert digest==expected,'PDF diferente do material curado'
    doc=fitz.open(pdf)
    # Páginas com colunas independentes, conferidas. Outras são largura total.
    segments=[]
    for page_index in [4,5,11,12,13,14]:
        page=doc[page_index]
        for left,right in [(0,page.rect.width/2),(page.rect.width/2,page.rect.width)]:
            text=page.get_text(clip=fitz.Rect(left,65,right,page.rect.height-55),sort=True)
            segments.append((page_index+1,text))
    extracted={}
    for page,text in segments:
        parts=re.split(r'(?m)^\s*(\d{1,2})\s*$',text)
        for i in range(1,len(parts),2):
            n=int(parts[i]);body=parts[i+1]
            if n not in NOTES: continue
            chunks=re.split(r'\(([A-E])\)',body)
            if len(chunks)!=11: continue
            choices={chunks[j]:clean(chunks[j+1]) for j in range(1,11,2)}
            choices['E']=re.split(r'\bRASCUNHO\b',choices['E'])[0].strip()
            extracted[n]=(page,clean(chunks[0]),choices)
    # Gabarito 1 ocupa o primeiro quarto da página 16; as outras versões não são utilizadas.
    p=doc[15]; keytext=p.get_text(clip=fitz.Rect(0,0,p.rect.width/4,p.rect.height),sort=True)
    keys={int(n):v for n,v in re.findall(r'(\d+)\s*-\s*([A-E])',keytext)}
    assert len(keys)==60, f'Gabarito incompleto: {len(keys)}'
    result=[]
    for n,(topic,explanation,alternatives) in NOTES.items():
        page,statement,choices=extracted[n]
        result.append(dict(id=f'basa-2013-1-{n:02}',disciplina='Língua Portuguesa' if n==10 else 'Matemática' if n<21 else 'Conhecimentos Bancários',assunto=topic,enunciado=statement,alternativas=choices,resposta_correta=keys[n],explicacao=explanation,explicacoes_alternativas=dict(zip('ABCDE',alternatives)),fonte=dict(concurso='Banco da Amazônia',banca='Cesgranrio',cargo='Técnico Bancário',ano=2013,arquivo=pdf.name,sha256=digest,pagina=page,questao=n,pagina_gabarito=16,versao='Gabarito 1'),status_validacao='gabarito_conferido',autoria_explicacao='Comentário didático autoral; não é comentário oficial da banca. Contexto da prova de 2013; normas e produtos podem ter mudado.'))
    assert len(result)==25
    output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(json.dumps(dict(schema_version=1,questions=result),ensure_ascii=False,indent=2)+'\n')
    print(f'{len(result)} questões extraídas e associadas ao gabarito 1 da página 16.')
if __name__=='__main__': build(Path(sys.argv[1]),Path(sys.argv[2]))
